values ('aws-certified-cloud-practitioner', 'CLF-C02', 'AWS Certified Cloud Practitioner', 'aws', 'foundational', 'cloud', 'The entry point to AWS. Validates cloud fluency, billing models and core services.', 'The AWS Certified Cloud Practitioner (CLF-C02) is the foundational AWS credential. It tests your understanding of cloud concepts, AWS global infrastructure, the shared responsibility model, core services, pricing and support plans. It is the fastest way to put a recognised cloud credential on a fresher CV and is frequently listed in Indian campus placement requirements.', 90, 65, '700 / 1000', array['English', 'Japanese', 'Korean', 'Simplified Chinese']::text[], 9500, 100, null, 'https://aws.amazon.com/certification/certified-cloud-practitioner/', 'Students, sales teams and non-technical professionals moving into cloud roles', 40, array['Cloud concepts', 'AWS core services', 'Security & compliance', 'Billing & pricing']::text[], '[{"question":"How long is the CLF-C02 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a CLF-C02 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."}]'::jsonb, 98, true)
