values ('aws-certified-solutions-architect-associate', 'SAA-C03', 'AWS Certified Solutions Architect – Associate', 'aws', 'associate', 'cloud', 'The most requested cloud certification in Indian job postings for mid-level engineers.', 'SAA-C03 is the highest-volume AWS certification worldwide and the one most frequently named in cloud engineer and DevOps job descriptions. You are tested on designing resilient, secure, high-performing and cost-optimised architectures across compute, storage, networking and databases.', 130, 65, '720 / 1000', array['English', 'Japanese', 'Korean', 'Simplified Chinese']::text[], 14700, 150, null, 'https://aws.amazon.com/certification/certified-solutions-architect-associate/', 'Cloud engineers and solution architects with 1+ years of hands-on AWS experience', 80, array['Architecture design', 'Networking', 'Storage & databases', 'Cost optimisation']::text[], '[{"question":"How long is the SAA-C03 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a SAA-C03 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."},{"question":"Is SAA-C03 still the current version?","answer":"Yes. SAA-C03 is the current exam version. AWS typically gives several months'' notice before retiring an exam version, and we flag pending retirements on this page as soon as they are announced."}]'::jsonb, 100, true)
