values ('aws-certified-developer-associate', 'DVA-C02', 'AWS Certified Developer – Associate', 'aws', 'associate', 'cloud', 'For engineers who build and deploy applications on AWS using SDKs and serverless.', 'AWS Certified Developer – Associate (DVA-C02) is a associate-level credential from Amazon Web Services. It is designed for application developers building on aws and is recognised by employers across India and globally.', 130, 65, '720 / 1000', array['English', 'Japanese', 'Korean', 'Simplified Chinese']::text[], 14700, 150, null, 'https://aws.amazon.com/certification/certified-developer-associate/', 'Application developers building on AWS', 75, array['Lambda', 'DynamoDB', 'CI/CD on AWS', 'IAM & security', 'SDK usage']::text[], '[{"question":"How long is the DVA-C02 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a DVA-C02 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."}]'::jsonb, 84, true)
