values ('aws-certified-sysops-administrator-associate', 'SOA-C03', 'AWS Certified SysOps Administrator – Associate', 'aws', 'associate', 'devops', 'Operations-focused AWS certification covering monitoring, automation and reliability.', 'AWS Certified SysOps Administrator – Associate (SOA-C03) is a associate-level credential from Amazon Web Services. It is designed for system administrators and operations engineers and is recognised by employers across India and globally.', 130, 65, '720 / 1000', array['English', 'Japanese', 'Korean', 'Simplified Chinese']::text[], 14700, 150, null, 'https://aws.amazon.com/certification/certified-sysops-admin-associate/', 'System administrators and operations engineers', 75, array['Monitoring', 'Automation', 'Deployment', 'Incident response', 'Cost control']::text[], '[{"question":"How long is the SOA-C03 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a SOA-C03 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."}]'::jsonb, 76, true)
