values ('aws-certified-solutions-architect-professional', 'SAP-C02', 'AWS Certified Solutions Architect – Professional', 'aws', 'professional', 'cloud', 'The senior architecture credential. Multi-account, migration and complex design.', 'AWS Certified Solutions Architect – Professional (SAP-C02) is a professional-level credential from Amazon Web Services. It is designed for senior architects with two or more years of aws design experience and is recognised by employers across India and globally.', 180, 75, '750 / 1000', array['English', 'Japanese', 'Korean', 'Simplified Chinese']::text[], 29400, 300, null, 'https://aws.amazon.com/certification/certified-solutions-architect-professional/', 'Senior architects with two or more years of AWS design experience', 120, array['Multi-account strategy', 'Migration', 'Hybrid networking', 'Governance']::text[], '[{"question":"How long is the SAP-C02 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a SAP-C02 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."}]'::jsonb, 71, true)
