values ('comptia-a-plus-core-1', '220-1101', 'CompTIA A+ Core 1', 'comptia', 'foundational', 'support', 'First of two exams for the A+ certification. Hardware, networking and troubleshooting.', 'CompTIA A+ is the standard entry credential for IT support roles. Certification requires passing two exams: Core 1 (220-1101) and Core 2 (220-1102). Core 1 covers mobile devices, networking, hardware, virtualisation and troubleshooting.', 90, 90, '675 / 900', array['English', 'German', 'Japanese', 'Portuguese', 'Spanish']::text[], 24000, 253, null, 'https://www.comptia.org/en-us/certifications/a/', 'Helpdesk technicians and desktop support engineers', 60, array['Hardware', 'Networking', 'Virtualisation', 'Troubleshooting']::text[], '[{"question":"How long is the 220-1101 voucher valid?","answer":"Vouchers we source are issued with a minimum 12-month validity from the date of delivery unless a specific expiry is shown on your offer. The expiry is confirmed in writing before you pay."},{"question":"Can I use a 220-1101 voucher in India?","answer":"Yes. These exams are delivered through the provider''s authorised testing network, which includes Pearson VUE test centres across India and online proctored delivery where the programme allows it."},{"question":"What happens if the voucher does not work?","answer":"We verify every code before delivery. If a code is rejected at the test centre or booking page, we replace it within one business day or refund you in full — your choice, not ours."}]'::jsonb, 87, true)
